import{_ as t,a as o,o as a,a6 as n}from"./chunks/framework.CJDy2q7X.js";const u=JSON.parse('{"title":"Notes","description":"","frontmatter":{"outline":false},"headers":[],"relativePath":"api/graphql-api/admin/customers/notes/index.md","filePath":"api/graphql-api/admin/customers/notes/index.md","lastUpdated":1787290888000}'),r={name:"api/graphql-api/admin/customers/notes/index.md"};function i(d,e,s,h,c,m){return a(),o("div",null,e[0]||(e[0]=[n('<h1 id="notes" tabindex="-1">Notes <a class="header-anchor" href="#notes" aria-label="Permalink to &quot;Notes&quot;">​</a></h1><p>The Notes menu records internal notes against a customer — the running log of comments the team keeps on an account (a support interaction, a fraud flag, a follow-up reminder). It mirrors the notes panel on the admin customer view screen.</p><h2 id="how-notes-work" tabindex="-1">How notes work <a class="header-anchor" href="#how-notes-work" aria-label="Permalink to &quot;How notes work&quot;">​</a></h2><p>Notes are <strong>append-only</strong>: each note is a separate, timestamped entry, and adding one never overwrites an earlier note. The notes list shows them newest-first. There is no edit or delete in this menu — the log is a permanent trail.</p><h2 id="notifying-the-customer" tabindex="-1">Notifying the customer <a class="header-anchor" href="#notifying-the-customer" aria-label="Permalink to &quot;Notifying the customer&quot;">​</a></h2><p>When adding a note you can set <code>customerNotified</code> to email the note&#39;s text to the customer. Leave it off to keep the note purely internal. Each note records whether the customer was notified.</p><h2 id="field-meanings" tabindex="-1">Field meanings <a class="header-anchor" href="#field-meanings" aria-label="Permalink to &quot;Field meanings&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Field</th><th>Meaning</th></tr></thead><tbody><tr><td><code>note</code></td><td>The note text.</td></tr><tr><td><code>customerId</code></td><td>The customer the note belongs to.</td></tr><tr><td><code>customerNotified</code></td><td>Whether the customer was emailed this note.</td></tr><tr><td><code>createdAt</code></td><td>When the note was added.</td></tr></tbody></table><h2 id="operations-in-this-menu" tabindex="-1">Operations in this menu <a class="header-anchor" href="#operations-in-this-menu" aria-label="Permalink to &quot;Operations in this menu&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Action</th><th>Operation</th></tr></thead><tbody><tr><td><a href="./list.html">List Notes</a></td><td><code>adminCustomerNotes(customerId:)</code> query</td></tr><tr><td><a href="./create.html">Add Note</a></td><td><code>createAdminCustomerNote</code> mutation</td></tr></tbody></table><p>Permission: <code>customers.customers.edit</code>.</p>',11)]))}const p=t(r,[["render",i]]);export{u as __pageData,p as default};
